      "id": "BIM.setElemsValidState",
      "name": "setElemsValidState",
      "namespace": "BIM",
      "module": "BIM（BIM）",
      "group": "渲染设置",
      "kind": "api",
      "callPath": "BlackHole3D.BIM.setElemsValidState",
      "description": "设置构件的有效性",
      "notes": [
        "注：该接口只针对构件有效，对地形数据无效"
      ],
      "parameters": [
        {
          "name": "dataSetId",
          "description": "表示要处理的数据集标识，为空串则表示处理所有数据集",
          "position": 1
        },
        {
          "name": "elemIdList",
          "description": "表示该项目对应的构件id数组，为空则表示该数据集下的全部构件",
          "position": 2
        },
        {
          "name": "enable",
          "description": "为true表示构件有效，为false表示构件无效，此时构件不可见，同时所有的接口操作都对这些构件无效",
          "position": 3
        }
      ],
      "models": [],
      "returns": [],
      "examples": [
        "BlackHole3D.BIM.setElemsValidState(\"dataSet01\",[1062,1014],);"
      ],
      "usageForms": [
        "call"
      ],
